<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue';import BaseModal from './BaseModal.vue';import {state,api,scope,changed,notify,ask,can} from '../lib/workspace';import {amount,inputMoney,cents,money,uid} from '../lib/format';
const props=defineProps({bank:Object});const emit=defineEmits(['close']);const cid=state.companyId;const titles=ref([]),error=ref(''),busy=ref(false),rows=ref([{title_id:'',amount:inputMoney(props.bank.remaining_cents)}]),reason=ref(''),settle=ref(false),key=uid();
const compatible=computed(()=>titles.value.filter(t=>!t.cancelled&&t.kind===(props.bank.amount_cents>0?'receivable':'payable')));const sum=computed(()=>rows.value.reduce((s,r)=>s+(cents(r.amount)||0),0));
onMounted(async()=>{state.editor={name:'Rateio bancário',companyId:cid};try{titles.value=await api(scope('/titles',cid));}catch(e){error.value=e.message;}});onUnmounted(()=>{state.editor=null;});
async function close(){if(busy.value)return;if(reason.value&&!await ask({title:'Descartar rateio?',message:'O rateio ainda não foi confirmado.',confirmLabel:'Descartar'}))return;emit('close');}
async function save(){busy.value=true;error.value='';try{await api(scope(`/banks/${props.bank.id}/allocate`,cid),{method:'POST',body:{reason:reason.value,settle:settle.value,idempotency_key:key,allocations:rows.value.map(r=>({title_id:r.title_id,amount:amount(r.amount),version:titles.value.find(t=>t.id===r.title_id)?.version}))}});changed();notify(settle.value?'Conciliação e baixas financeiras registradas.':'Conciliação registrada sem gerar baixa.');emit('close');}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><BaseModal title="Conciliar por rateio" :subtitle="bank.description" wide @close="close"><p v-if="error" class="message error">{{error}}</p><p>Disponível no banco: {{money(bank.remaining_cents)}} · alocado nesta operação: {{money(sum)}}</p><form id="allocation-form" @submit.prevent="save"><div v-for="(r,i) in rows" :key="i" class="form-grid three"><label>Título<select v-model.number="r.title_id" required><option value="">Selecione</option><option v-for="t in compatible" :key="t.id" :value="t.id">#{{t.id}} · {{t.partner_name}} · {{t.description}} · {{money(t.amount_cents)}}</option></select></label><label>Valor do vínculo (R$)<input v-model="r.amount" required/></label><button type="button" class="text-button" @click="rows.splice(i,1)" :disabled="rows.length===1">Remover</button></div><button type="button" class="button outline" @click="rows.push({title_id:'',amount:''})">Adicionar título ao rateio</button><label>Justificativa *<textarea v-model="reason" required/></label><label class="choice-card"><input v-model="settle" type="checkbox" :disabled="!can('financial.settlements','settle')"/><div><strong>Também registrar baixas pelo valor de cada vínculo</strong><small>Usa a data do extrato e abate o principal. Não gera juros, descontos ou lançamento contábil.</small></div></label><p class="message subtle">{{settle?'Esta ação concilia e baixa os títulos na data do extrato.':'Esta ação apenas concilia. Os saldos financeiros não serão alterados.'}}</p></form><template #footer><button class="button" @click="close" :disabled="busy">Cancelar</button><button class="button primary" form="allocation-form" :disabled="busy||sum>bank.remaining_cents">{{settle?'Conciliar e baixar':'Confirmar vínculos'}}</button></template></BaseModal></template>
